protected void initializeDataAcessor()
{
    next initializeDataAcessor();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        pricingManager = new GUPRetailPricingDataManager(currentChannel.RecId, this.getTransactionId(), tempOrderItem, true);
    }
}

protected RetailSalesPriceAdjustmentLineMap initRetailSalesPriceAdjustmentLineMap(RetailSalesPriceAdjustmentLineMap                       _adjustmentLine,
                                                                                  RetailOrderLineMap                                      _retailOrderLineMap,
                                                                                  Microsoft.Dynamics.Commerce.Runtime.DataModel.PriceLine _crtPriceLine)
{
    _adjustmentLine = next initRetailSalesPriceAdjustmentLineMap(_adjustmentLine, _retailOrderLineMap, _crtPriceLine);

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        Microsoft.Dynamics.Commerce.Runtime.DataModel.AttributePricingAdjustmentPriceLine adjustmentPriceLine = _crtPriceLine as Microsoft.Dynamics.Commerce.Runtime.DataModel.AttributePricingAdjustmentPriceLine;

        _adjustmentLine.Amount = (-adjustmentPriceLine.get_AdjustedAmount());
    }

    return _adjustmentLine;
}
